input.content:
workspace "Bookshop" "A simple online bookshop" {

    model {
        customer = person "Customer" "A customer who browses the book catalogue and places orders online."

        bookshop = softwareSystem "Bookshop" "An online bookshop where customers browse books and place orders." {
            webStore = container "Web Store" "The web application customers use to browse the catalogue and place orders." "React SPA"
            orderProcessor = container "Order Processor" "Processes and confirms customer orders." "Node.js service"
        }

        customer -> webStore "Browses the catalogue and places orders through" "HTTPS/JSON"
        webStore -> orderProcessor "Submits new orders to" "HTTP/JSON"
    }

    views {
        systemContext bookshop "Bookshop System Context" "Shows the Customer and the Bookshop system." {
            include *
            autoLayout
        }

        updateViews
    }

    configuration {
        scope softwaresystem
    }
}

